function extras(){const E={h:[],t:[]};
 if(S.wand&&D.profiles[S.wand])E.h.push({key:'w',model:S.wand,name:S.wand,kind:'Wanderer',stats:D.profiles[S.wand].slice(0,9),mfw:(D.wmwf&&D.wmwf[S.wand])||[1,1,1],info:(w=>w?[...[['Wargear',w.wargear],['Azioni eroiche',w.heroic],['Regole speciali',w.special]].map(([l,a])=>[l,(a||[]).join(', ')]),...(w.extra||[])].filter(a=>a[1]):null)(D.wdata&&D.wdata[S.wand])});
 S.h.forEach(h=>{if(!(h.model||h.name))return;(h.g.eq||[]).forEach((e,j)=>{const pn=D.creatures&&D.creatures[e];if(pn&&D.profiles[pn]){if(!h.id)h.id=uid();const raw=D.profiles[pn].slice(0,9),os=hero(Object.assign({},h,{miss:false})).tot,star=raw.some(v=>v==='*');E.t.push({key:`c_${h.id}_${j}`,model:pn,name:pn,kind:'Creatura',owner:h.name||h.model,hmiss:!!h.miss,stats:raw.map((v,i)=>v==='*'?os[i]:v),star,info:(c=>c&&c.special&&c.special.length?[['Regole speciali',c.special.join(', ')]]:null)(D.cdata&&D.cdata[pn])})}})});return E}
