const exInfo=e=>e.info&&e.info.length?`<div class="xinfo">${e.info.map(([l,s])=>`<div class="xi"><b>${esc(l)}</b><span>${esc(s)}</span></div>`).join('')}</div>`:'';
const exCard=e=>{const st=(S.ex&&S.ex[e.key])||{},w=e.kind==='Wanderer';
 return`<div class="card">${pic('ex.'+e.key,st.img,1)}<h3><span>${esc(e.name)}</span><span>${e.temp?'temporaneo':w?'+70 pt':'inclusa nel costo'}</span></h3><div class="st" style="margin-top:6px">${LBL.map(l=>`<b>${l}</b>`).join('')}${e.stats.map(x=>`<span class="t tt">${x}</span>`).join('')}</div>${w?`<div class="mw" style="margin-top:8px">${['Might','Will','Fate'].map((n,j)=>`<div class="ctr"><b>${n}</b><div class="mfv">${e.mfw[j]}</div></div>`).join('')}</div>`:''}${exInfo(e)}<p class="xnote">${w?'Wanderer scelto nella Panoramica · non guadagna XP':'Creatura di <b>'+esc(e.owner)+'</b> (Equipaggiamento)'+(e.star?' · Coraggio uguale a quello dell\'eroe':'')+' · non guadagna XP'}</p></div>`};
